/* ===== src/tokens.css ===== */
/*
 * 木刻侧影 / SillyTavern 1.14.0
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */

@font-face {
    font-family: "Woodcut Source Han Serif SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Woodcut Zhuque Fangsong";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --wc-ink: #352419;
    --wc-ink-soft: #6b513c;
    --wc-paper: #ead9b5;
    --wc-paper-light: #f4e7c9;
    --wc-paper-deep: #cfb789;
    --wc-walnut: #28180f;
    --wc-walnut-soft: #452a19;
    --wc-walnut-light: #70472a;
    --wc-gold: #c7a35e;
    --wc-gold-light: #e0c784;
    --wc-copper: #9b613a;
    --wc-danger: #9b3f32;
    --wc-success: #5f7748;
    --wc-info: #5d7180;
    --wc-disabled: #8a765f;
    --wc-line: rgba(72, 42, 22, 0.56);
    --wc-shadow: rgba(28, 15, 8, 0.42);
    --wc-focus: #e4c471;
    --wc-state-surface: #f4e7c9;
    --wc-state-surface-muted: #ddcaa4;
    --wc-state-surface-selected: #c7a35e;
    --wc-state-surface-disabled: #bea885;
    --wc-state-text-primary: #352419;
    --wc-state-text-secondary: #6b513c;
    --wc-state-text-disabled: #8a765f;
    --wc-prompt-surface: #f0dfbd;
    --wc-prompt-surface-disabled: #e0c58f;
    --wc-prompt-text-disabled: #694125;
    --wc-prompt-border-disabled: #9b613a;
    --wc-prompt-toggle-off: #a66f3e;
    --wc-state-border: #70472a;
    --wc-state-focus-ring: #e4c471;
    --wc-state-opacity-disabled: 0.78;
    --wc-state-opacity-one: 1;
    --wc-state-filter-none: none;
    --wc-state-text-shadow-none: none;
    --wc-state-box-shadow-none: none;
    --wc-overflow-auto: auto;
    --wc-state-shadow: 0 0.35rem 0.8rem rgba(28, 15, 8, 0.28);
    --wc-code-inline-surface: #452a19;
    --wc-code-block-surface: #21150e;
    --wc-code-text: #f4e7c9;
    --wc-code-muted: #c1aa86;
    --wc-code-accent: #e0c784;
    --wc-code-selection: #70472a;
    --wc-radius-sm: 0.35rem;
    --wc-radius-md: 0.7rem;
    --wc-radius-lg: 1.1rem;
    --wc-gap-xs: 0.3rem;
    --wc-gap-sm: 0.55rem;
    --wc-gap-md: 0.9rem;
    --wc-gap-lg: 1.45rem;
    --wc-speed: 150ms;
    --wc-font-body: "Woodcut Source Han Serif SC", "Noto Serif SC", "Songti SC", serif;
    --wc-font-display: "Woodcut Zhuque Fangsong", "FangSong", "STFangsong", serif;
    --wc-wood-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/62afad41d404262e2d212433f308da03764e414f/assets/%E6%9C%A8%E5%88%BB%E4%BE%A7%E5%BD%B1/walnut-carved-texture.webp");
    --wc-paper-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/62afad41d404262e2d212433f308da03764e414f/assets/%E6%9C%A8%E5%88%BB%E4%BE%A7%E5%BD%B1/warm-parchment-texture.webp");
    --wc-frame-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/62afad41d404262e2d212433f308da03764e414f/assets/%E6%9C%A8%E5%88%BB%E4%BE%A7%E5%BD%B1/user-avatar-frame.webp");
    --wc-character-header-shell-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/62afad41d404262e2d212433f308da03764e414f/assets/%E6%9C%A8%E5%88%BB%E4%BE%A7%E5%BD%B1/character-header-shell-v24.webp");
    --wc-user-frame-size: clamp(11rem, 22vw, 18rem);
    --wc-character-frame-size: clamp(9.2rem, 15vw, 12.5rem);
    --wc-character-page-border: 0.5rem;
    --wc-avatar-inner-size: 61%;
    --wc-avatar-gap: 0.75rem;
    --wc-side-rail: clamp(1.15rem, 2.9vw, 2.3rem);
    --wc-workbench-depth: clamp(0.55rem, 1.4vw, 0.9rem);
    --wc-panel-shadow: 0 0.7rem 1.6rem var(--wc-shadow);
    --mainFontFamily: var(--wc-font-body);
    --SmartThemeBodyColor: var(--wc-ink);
    --SmartThemeEmColor: #6d3d27;
    --SmartThemeUnderlineColor: #86522f;
    --SmartThemeQuoteColor: #7b5534;
    --SmartThemeBlurTintColor: rgba(234, 217, 181, 0.97);
    --SmartThemeChatTintColor: rgba(234, 217, 181, 0.96);
    --SmartThemeUserMesBlurTintColor: rgba(52, 31, 19, 0.97);
    --SmartThemeBotMesBlurTintColor: rgba(244, 231, 201, 0.97);
    --SmartThemeShadowColor: rgba(28, 15, 8, 0.3);
    --SmartThemeBorderColor: rgba(91, 55, 31, 0.58);
}


/* ===== src/kernel/interaction-protection.css ===== */
/*
 * 功能保护：不决定主题构图。
 * 所有装饰层不接管点击；真实控件保留焦点、禁用和生成状态。
 */

#chat .mes:not(.smallSysMes) .mesAvatarWrapper::after,
#send_form::before,
#top-settings-holder::before,
#form_sheld::before {
    pointer-events: none;
}

:is(
    #top-settings-holder,
    #send_form,
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    #completion_prompt_manager,
    #completion_prompt_manager_popup
) :is(button, input, select, textarea, [tabindex], .interactable):focus-visible,
#chat :is(.mes_button, .avatar, summary, a):focus-visible {
    outline: 2px solid var(--wc-focus);
    outline-offset: 2px;
}

:is(#send_but, #mes_stop, #options_button, #extensionsMenuButton) {
    position: relative;
    isolation: isolate;
}

:is(#send_but, #mes_stop, #options_button, #extensionsMenuButton)[aria-disabled="true"],
:is(#send_form, #top-settings-holder) :disabled {
    color: var(--wc-disabled);
    cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
    :is(#chat, #top-settings-holder, #send_form) * {
        transition-duration: 0.01ms;
    }
}


/* ===== src/kernel/scrollbars.css ===== */
/*
 * 仅隐藏滚动条轨道与拇指外观。
 * 不修改 overflow、touch-action 或 pointer-events；滚轮、触摸、键盘、
 * 抽屉、代码块、表格、Select2 与文本域滚动继续由原生节点负责。
 */
* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

::-webkit-scrollbar {
    display: none !important;
}


/* ===== src/chat-layout.css ===== */
/*
 * 外壳：L13 双真实头像木雕刊记。
 * User 使用大型徽章与短题签；Character 使用独立头像框与框下整宽长文。
 */

body {
    background-color: var(--wc-walnut);
    background-image: var(--wc-wood-image);
    background-size: 46rem auto;
    background-repeat: repeat;
    background-position: center top;
}

#bg1 {
    background-color: var(--wc-walnut) !important;
    background-image: var(--wc-wood-image) !important;
    background-repeat: repeat !important;
    background-position: center top !important;
    background-size: 46rem auto !important;
    filter: none;
}

#chat {
    box-sizing: border-box;
    color: var(--wc-ink);
    background-color: var(--wc-paper);
    background-image:
        linear-gradient(rgba(244, 231, 201, 0.68), rgba(230, 211, 172, 0.68)),
        var(--wc-paper-image);
    background-repeat: repeat;
    background-size: auto, 44rem auto;
    border-style: solid;
    border-width: 0 var(--wc-side-rail);
    border-color: var(--wc-walnut);
    border-image: var(--wc-wood-image) 42 round;
    outline: none;
    outline-offset: 0;
    text-shadow: none;
    box-shadow: none;
}

#chat .mes {
    color: var(--wc-ink);
}

#chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--wc-avatar-gap);
    min-width: 0;
}

#chat .mes[is_user="true"]:not(.smallSysMes) {
    padding: clamp(1.35rem, 4vw, 3rem) clamp(0.7rem, 3vw, 2rem) 1.5rem;
}

#chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) .mesAvatarWrapper {
    display: block;
    position: relative;
    flex: 0 0 auto;
    padding: 0;
    margin: 0 auto;
    isolation: isolate;
}

#chat .mes[is_user="true"]:not(.smallSysMes) .mesAvatarWrapper {
    width: var(--wc-user-frame-size);
    height: var(--wc-user-frame-size);
    min-width: var(--wc-user-frame-size);
    min-height: var(--wc-user-frame-size);
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper {
    width: var(--wc-character-frame-size);
    height: var(--wc-character-frame-size);
    min-width: var(--wc-character-frame-size);
    min-height: var(--wc-character-frame-size);
}

#chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes).last_mes .mesAvatarWrapper {
    padding-bottom: 0;
}

#chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) .mesAvatarWrapper .avatar {
    display: block;
    position: absolute;
    inset: calc((100% - var(--wc-avatar-inner-size)) / 2);
    width: var(--wc-avatar-inner-size);
    height: var(--wc-avatar-inner-size);
    min-width: 0;
    min-height: 0;
    overflow: hidden;
    border-radius: 50%;
    background: var(--wc-walnut-soft);
    box-shadow: inset 0 0 0 2px var(--wc-gold), 0 0.45rem 1rem var(--wc-shadow);
}

#chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    border: 0;
    border-radius: 50%;
    object-fit: cover;
    box-shadow: none;
    filter: none;
}

#chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) .mesAvatarWrapper::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 2;
    background-image: var(--wc-frame-image);
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    filter: drop-shadow(0 0.55rem 0.65rem rgba(22, 11, 5, 0.42));
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper::after {
    content: none;
    background-image: none;
}

#chat .mes[is_user="true"]:not(.smallSysMes) .mes_block {
    width: min(100%, 43rem);
    padding: 0;
    overflow: visible;
    text-align: center;
}

#chat .mes[is_user="true"]:not(.smallSysMes) .ch_name {
    justify-content: center;
    min-height: 0;
    margin: 0 auto 0.35rem;
    color: var(--wc-ink-soft);
    font-family: var(--wc-font-display);
    font-weight: 400;
    letter-spacing: 0.12em;
}

#chat .mes[is_user="true"]:not(.smallSysMes) .mes_text {
    margin: 0 auto;
    padding: 0.78em clamp(1.2em, 4vw, 2.25em);
    color: var(--wc-paper-light);
    background-color: var(--wc-walnut-soft);
    background-image:
        linear-gradient(rgba(40, 24, 15, 0.3), rgba(40, 24, 15, 0.3)),
        var(--wc-wood-image);
    background-size: auto, 34rem auto;
    border: 1px solid rgba(224, 199, 132, 0.42);
    border-radius: var(--wc-radius-sm);
    box-shadow:
        inset 0 1px rgba(255, 235, 173, 0.18),
        inset 0 -2px rgba(16, 8, 4, 0.48),
        0 0.5rem 1rem rgba(38, 20, 10, 0.24);
    font-family: var(--wc-font-display);
    font-size: 1em;
    line-height: 1.7;
    letter-spacing: 0.06em;
    text-align: center;
}

#chat .mes[is_user="true"]:not(.smallSysMes) :is(.mes_timer, .timestamp, .mesIDDisplay, .tokenCounterDisplay) {
    color: var(--wc-ink-soft);
    font-family: var(--wc-font-display);
    font-weight: 400;
    opacity: 0.9;
}

#chat .mes[is_user="false"][is_system="false"] {
    --wc-character-message-pad-top: clamp(1rem, 2.4vw, 1.8rem);
    --wc-character-message-pad-x: clamp(0.3rem, 0.9vw, 0.65rem);
    --wc-character-page-padding: 0rem;
    --wc-character-page-border: 0rem;
    display: block;
    position: relative;
    padding: var(--wc-character-message-pad-top) var(--wc-character-message-pad-x) 2rem;
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper {
    position: absolute;
    z-index: auto;
    isolation: auto;
    top: var(--wc-character-message-pad-top);
    left: 50%;
    width: calc(100% - var(--wc-character-message-pad-x) - var(--wc-character-message-pad-x) - var(--wc-character-page-padding) - var(--wc-character-page-padding) - var(--wc-character-page-border) - var(--wc-character-page-border));
    height: auto;
    min-width: 0;
    min-height: 0;
    aspect-ratio: 1835 / 484;
    margin: 0;
    overflow: visible;
    transform: translateX(-50%);
    pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 2;
    pointer-events: none;
    background-image: var(--wc-character-header-shell-image);
    background-repeat: no-repeat;
    background-position: center;
    background-size: 100% 100%;
    filter: none;
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper .avatar {
    position: absolute;
    z-index: 1;
    inset: auto;
    top: 20.25%;
    left: 7.3%;
    width: 14.88%;
    height: auto;
    min-width: 0;
    min-height: 0;
    aspect-ratio: 1;
    flex: none;
    margin: 0;
    padding: 0;
    overflow: hidden;
    border-radius: 50%;
    clip-path: circle(50% at 50% 50%);
    transform: none;
    box-shadow: none;
    pointer-events: auto;
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    aspect-ratio: 1;
    margin: 0;
    padding: 0;
    object-fit: cover;
    object-position: center;
    border: 0;
    border-radius: 50%;
    clip-path: circle(50% at 50% 50%);
    filter: none;
    box-shadow: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block {
    position: relative;
    box-sizing: border-box;
    width: 100%;
    margin-inline: auto;
    padding: 0;
    min-width: 0;
    overflow: visible;
    background-color: transparent;
    background-image: none;
    background-size: auto;
    border: 0;
    border-image: none;
    border-radius: 0;
    outline: none;
    outline-offset: 0;
    box-shadow: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::before {
    content: none;
    border: 0;
    box-shadow: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::after {
    content: none;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
    position: relative;
    z-index: 3;
    isolation: auto;
    display: block;
    box-sizing: border-box;
    width: 100%;
    min-height: 0;
    aspect-ratio: 1835 / 484;
    margin: 0 0 clamp(1.05rem, 2.5vw, 1.55rem);
    padding: 0;
    color: var(--wc-paper-light);
    background: none;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    font-family: var(--wc-font-display);
    font-weight: 400;
    letter-spacing: 0.08em;
    clip-path: none;
    filter: none;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name::before {
    content: none;
    background-image: none;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name::after {
    content: none;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container.flex1 {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: block;
    min-width: 0;
}

/* Native action groups must remain above the full-header metadata box.
 * Do not override display: the host toggles normal/edit controls itself. */
#chat .mes[is_user="false"][is_system="false"] .ch_name > :is(.mes_buttons, .mes_edit_buttons) {
    position: relative;
    z-index: 2;
    pointer-events: auto;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container.flex1 > .flex-container.alignItemsBaseline {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: grid !important;
    grid-template-columns: 34% 25% 3% 17% 21%;
    grid-template-rows: 100%;
    width: 100%;
    height: 100%;
    min-width: 0;
    align-items: center !important;
    gap: 0;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name .name_text {
    position: relative;
    z-index: 2;
    grid-column: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
    font-family: "STKaiti", "KaiTi", var(--wc-font-display);
    overflow: hidden;
    font-size: clamp(1.35rem, 2.25vw, 2rem);
    line-height: 1;
    letter-spacing: 0.08em;
    text-align: center;
    text-shadow: 0 1px 0 rgba(255, 235, 173, 0.16), 0 -1px 0 rgba(18, 8, 3, 0.78);
    white-space: nowrap;
    text-overflow: ellipsis;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name .mes_ghost {
    grid-column: 3;
    justify-self: center;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name :is(.timestamp, .timestamp-icon, .mes_timer, .tokenCounterDisplay) {
    position: relative;
    z-index: 2;
    color: var(--wc-gold-light);
    font-family: var(--wc-font-body);
    font-size: clamp(0.56rem, 0.68vw, 0.68rem);
    line-height: 1.25;
    letter-spacing: 0.04em;
    opacity: 1;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name .timestamp {
    grid-column: 4;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    width: 100%;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
    text-decoration: none;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: normal;
    text-align: center;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name .timestamp::before {
    content: "时间：";
    margin-inline-end: 0.3em;
    color: var(--wc-gold-light);
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper .mesIDDisplay {
    position: absolute;
    z-index: 4;
    top: 34%;
    left: 80.6%;
    display: flex;
    width: 10%;
    height: 32%;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    margin: 0;
    padding: 0;
    color: var(--wc-gold-light);
    font-family: var(--wc-font-display);
    font-size: clamp(0.58em, 0.72vw, 0.72em);
    font-weight: 400;
    line-height: 1.05;
    letter-spacing: 0.04em;
    text-align: center;
    opacity: 1;
    filter: none;
    text-shadow: 0 -1px 0 rgba(18, 8, 3, 0.82);
    pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper .mesIDDisplay::before {
    content: "楼层";
    display: block;
    margin-bottom: 0.12em;
    font-size: 0.82em;
    letter-spacing: 0.1em;
}

body.documentstyle #chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) .mesAvatarWrapper {
    display: block !important;
}

body.documentstyle #chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) .mes_block .ch_name :is(.name_text, .timestamp, .timestamp-icon) {
    display: inline-flex !important;
}

body.documentstyle #chat .mes:is([is_user="true"], [is_user="false"][is_system="false"]):not(.smallSysMes) .mes_text {
    margin-inline: 0;
}

body.documentstyle #chat .mes[is_user="false"][is_system="false"] .mes_block {
    margin-inline: auto;
}

#chat .mes[is_system="true"] {
    margin: 0.5rem auto;
    color: var(--wc-ink-soft);
}

#chat .mes_buttons,
#chat :is(.swipe_left, .swipe_right, .swipes-counter) {
    color: var(--wc-copper);
    opacity: 1;
    text-shadow: none;
}

#chat .mes.selected {
