/* ===== src/full-text.css ===== */
/*
 * T01 开放式羊皮纸阅读页；正文直接落在聊天纸面，不使用嵌套卡片或侧边阴影。
 */

#chat .mes_text {
    color: var(--wc-ink);
    font-family: var(--wc-font-body);
    font-size: 1em;
    font-weight: 400;
    line-height: 1.85;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    position: relative;
    z-index: 1;
    box-sizing: border-box;
    width: 100%;
    max-width: none;
    margin-inline: 0;
    padding: 0.35em clamp(1.1rem, 2.4vw, 1.8rem) clamp(1.6rem, 2.7vw, 2.25rem);
    font-size: 1.16em;
    line-height: 1.72;
    text-align: start;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text::before {
    content: "◆  ◇  ◆";
    display: block;
    margin: 0 0 1.05em;
    color: var(--wc-copper);
    font-family: var(--wc-font-display);
    font-size: 0.68em;
    letter-spacing: 0.42em;
    line-height: 1;
    text-align: center;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text > p {
    margin-block: 0 0.82em;
    text-indent: 2em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text > p:first-of-type::first-letter {
    float: inline-start;
    margin: 0.08em 0.16em 0 0;
    color: var(--wc-walnut-soft);
    font-family: var(--wc-font-display);
    font-size: 2.15em;
    line-height: 0.9;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    margin-block: 1.1em 0.55em;
    color: var(--wc-walnut-soft);
    font-family: var(--wc-font-display);
    font-weight: 400;
    letter-spacing: 0.08em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text :is(h1, h2, h3) {
    padding-block: 0.18em 0.24em;
    text-align: center;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text :is(ul, ol) {
    margin-block: 0.8em 1em;
    padding-inline-start: 2.2em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text li::marker {
    color: var(--wc-copper);
}

#chat .mes_text :is(strong, b) {
    color: #5f3922;
    font-family: var(--wc-font-display);
    font-weight: 400;
    letter-spacing: 0.035em;
}

#chat .mes_text :is(em, i) {
