}


/* ===== src/windows/top-bar.css ===== */
/*
 * 只改入口视觉，不修改承载展开内容的 .drawer 几何。
 */

#top-settings-holder {
    position: relative;
    isolation: isolate;
    color: var(--wc-gold);
    background-color: var(--wc-walnut);
    background-image:
        linear-gradient(rgba(31, 18, 11, 0.16), rgba(31, 18, 11, 0.16)),
        var(--wc-wood-image);
    background-size: auto, 38rem auto;
    border-top: 1px solid rgba(224, 199, 132, 0.28);
    border-bottom: 0;
    box-shadow: inset 0 1px rgba(255, 231, 161, 0.14);
}

#top-settings-holder::before,
#top-settings-holder::after {
    content: "\f06c";
    position: absolute;
    top: 50%;
    z-index: 2;
    display: block;
    color: var(--wc-gold);
    font-family: "Font Awesome 6 Free";
    font-size: clamp(0.95rem, 1.3vw, 1.35rem);
    font-style: normal;
    font-weight: 900;
    line-height: 1;
    opacity: 1;
    filter: none;
    text-shadow:
        0 1px 0 rgba(255, 231, 161, 0.25),
        0 -1px 0 rgba(19, 9, 4, 0.82);
    pointer-events: none;
}

#top-settings-holder::before {
    left: 0.48rem;
    transform: translateY(-50%) rotate(-22deg);
}

#top-settings-holder::after {
    right: 0.48rem;
    transform: translateY(-50%) scaleX(-1) rotate(-22deg);
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon) {
    color: var(--wc-gold);
    background: transparent;
    border: 0;
    opacity: 1;
    filter: none;
    text-shadow:
        0 1px 0 rgba(255, 231, 161, 0.28),
        0 -1px 0 rgba(19, 9, 4, 0.85),
        1px 0 0 rgba(19, 9, 4, 0.42);
    transition: color var(--wc-speed), transform var(--wc-speed);
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon):hover,
#top-settings-holder :is(.drawer-toggle, .drawer-icon):focus-visible {
    color: var(--wc-gold-light);
    opacity: 1;
    filter: none;
    transform: translateY(-1px) scale(1.06);
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon).openIcon,
#top-settings-holder .drawer-toggle:has(+ .drawer-content.openDrawer) {
    color: var(--wc-paper-light);
    opacity: 1;
    filter: none;
    text-decoration: none;
}

#top-settings-holder .drawer-icon.closedIcon {
    color: var(--wc-gold);
    opacity: 1;
    filter: none;
}


