:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup) :is(input[type="checkbox"], input[type="radio"], input[type="range"]):disabled {
    accent-color: var(--wc-state-text-disabled);
    opacity: var(--wc-state-opacity-disabled);
    filter: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup) :is(input[type="checkbox"], input[type="radio"], input[type="range"]):focus-visible {
    outline: 2px solid var(--wc-state-focus-ring);
    outline-offset: 2px;
}

/* 消息操作、顶栏与输入动作 */
#chat .mes_buttons .mes_button,
#chat :is(.mes_edit, .mes_more) {
    color: var(--wc-copper);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#chat .mes_buttons .mes_button:hover,
#chat :is(.mes_edit, .mes_more):hover {
    color: var(--wc-gold-light);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#chat .mes_buttons .mes_button:disabled,
#chat :is(.mes_edit, .mes_more).disabled {
    color: var(--wc-state-text-disabled);
    opacity: var(--wc-state-opacity-disabled);
    filter: none;
    text-shadow: none;
}

#chat .mes_buttons .mes_button:focus-visible,
#chat :is(.mes_edit, .mes_more):focus-visible {
    color: var(--wc-gold-light);
    outline: 2px solid var(--wc-state-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon) {
    color: var(--wc-gold);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon):hover {
    color: var(--wc-gold-light);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon).openIcon {
    color: var(--wc-code-text);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon):focus-visible,
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop):focus-visible {
    color: var(--wc-gold-light);
    outline: 2px solid var(--wc-state-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#send_form #options_button,
#send_form #extensionsMenuButton,
#send_form #send_but,
#send_form #mes_stop {
    color: var(--wc-gold);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#send_form #mes_stop {
    color: var(--wc-danger);
}

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop):disabled,
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop)[aria-disabled="true"] {
    color: var(--wc-state-text-disabled);
    opacity: var(--wc-state-opacity-disabled);
    filter: none;
    text-shadow: none;
}

/* 抽屉标题 */
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.standoutHeader, .inline-drawer-toggle.inline-drawer-header) {
    color: var(--wc-code-text);
    background: var(--wc-code-inline-surface);
    border-color: var(--wc-state-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.standoutHeader, .inline-drawer-toggle.inline-drawer-header).disabled {
    color: var(--wc-state-text-disabled);
    background: var(--wc-state-surface-disabled);
    border-color: var(--wc-state-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(.standoutHeader, .inline-drawer-toggle.inline-drawer-header) :is(.fa-solid, .fa-regular) {
    color: inherit;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* 通知 */
#toast-container > .toast {
    color: var(--wc-state-text-primary);
    background: var(--wc-state-surface);
    border: 1px solid var(--wc-state-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

body #toast-container > .toast:is(.toast-success, .toast-warning, .toast-error, .toast-info) {
    color: var(--wc-state-text-primary);
    background-color: var(--wc-state-surface);
    border-color: var(--wc-state-border);
    box-shadow: 0 0.42rem 0.9rem rgba(77, 44, 23, 0.38);
    opacity: 1;
    filter: none;
}

body #toast-container > .toast.toast-success { border-left: 0.32rem solid var(--wc-success); }
body #toast-container > .toast.toast-warning { border-left: 0.32rem solid var(--wc-gold); }
body #toast-container > .toast.toast-error { border-left: 0.32rem solid var(--wc-danger); }
body #toast-container > .toast.toast-info { border-left: 0.32rem solid var(--wc-info); }

#toast-container :is(.toast-title, .toast-message, .toast-close-button) {
    color: var(--wc-state-text-primary);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#toast-container .toast-close-button:focus-visible {
    color: var(--wc-state-text-primary);
    outline: 2px solid var(--wc-state-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* 独立挂载层项目 */
.select2-dropdown .select2-results__option {
    color: var(--wc-state-text-primary);
    background: var(--wc-state-surface);
    border-color: transparent;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

.select2-dropdown .select2-results__option--highlighted {
    color: var(--wc-code-text);
    background: var(--wc-code-inline-surface);
    border-color: var(--wc-state-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

.select2-dropdown .select2-results__option--selected {
    color: var(--wc-state-text-primary);
    background: var(--wc-state-surface-selected);
    border-color: var(--wc-state-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

.select2-dropdown .select2-results__option--disabled {
    color: var(--wc-state-text-disabled);
    background: var(--wc-state-surface-disabled);
    border-color: transparent;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

.select2-dropdown .select2-results__option:focus-visible {
    color: var(--wc-state-text-primary);
    outline: 2px solid var(--wc-state-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
}


/* ===== src/windows/transient-ui.css ===== */
.popup,
#dialogue_popup,
#character_popup,
#extensionsMenu,
.options-content {
    color: var(--wc-ink);
    background-color: var(--wc-paper);
    background-image: var(--wc-paper-image);
    background-size: 34rem auto;
    border: 1px solid var(--wc-line);
    border-radius: var(--wc-radius-md);
    box-shadow: var(--wc-panel-shadow);
    text-shadow: none;
}

.popup :is(h1, h2, h3, h4, .popup-title),
#dialogue_popup :is(h1, h2, h3, h4, .popup-title) {
    color: var(--wc-walnut-soft);
    font-family: var(--wc-font-display);
    font-weight: 400;
}

.popup :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]), select, textarea),
#dialogue_popup :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]), select, textarea) {
    color: var(--wc-ink);
    background: rgba(244, 231, 201, 0.88);
    border-color: var(--wc-line);
    font-family: var(--wc-font-body);
}

.popup :is(button, .menu_button),
#dialogue_popup :is(button, .menu_button) {
    color: var(--wc-paper-light);
    background-color: var(--wc-walnut-soft);
    background-image: var(--wc-wood-image);
    background-size: 30rem auto;
    border: 1px solid rgba(199, 163, 94, 0.5);
    text-shadow: none;
}

#toast-container > .toast {
    color: var(--wc-ink);
    background-color: var(--wc-paper-light);
    background-repeat: no-repeat;
    background-position: 0.8rem center;
    background-size: 1.35rem 1.35rem;
    border: 1px solid var(--wc-line);
    border-left: 0.32rem solid var(--wc-info);
    box-shadow: var(--wc-panel-shadow);
    opacity: 1;
    text-shadow: none;
}

#toast-container > .toast-success {
    border-left-color: var(--wc-success);
}

#toast-container > .toast-warning {
    border-left-color: var(--wc-gold);
}

#toast-container > .toast-error {
    border-left-color: var(--wc-danger);
}

#toast-container > .toast-info {
    border-left-color: var(--wc-info);
}

#toast-container .toast-title {
    color: var(--wc-walnut-soft);
    font-family: var(--wc-font-display);
    font-weight: 400;
}

#toast-container .toast-message,
#toast-container .toast-close-button {
    color: var(--wc-ink);
    text-shadow: none;
}

.select2-dropdown {
    color: var(--wc-ink);
    background-color: var(--wc-paper-light);
    background-image: var(--wc-paper-image);
    background-size: 32rem auto;
    border-color: var(--wc-line) !important;
    box-shadow: var(--wc-panel-shadow);
    text-shadow: none;
}


/* ===== src/windows/mobile.css ===== */
@media (max-width: 700px) {
    :root {
        --wc-user-frame-size: clamp(9.2rem, 48vw, 13rem);
        --wc-character-frame-size: clamp(6.8rem, 32vw, 8.6rem);
        --wc-avatar-gap: 0.55rem;
        --wc-side-rail: clamp(0.5rem, 2vw, 0.72rem);
        --wc-workbench-depth: 0.38rem;
    }

    #chat {
        border-width: 0 var(--wc-side-rail);
        background-size: auto, 30rem auto;
        outline: none;
        box-shadow: none;
    }

    #chat .mes[is_user="true"]:not(.smallSysMes) {
        gap: var(--wc-avatar-gap);
        padding: 1.25rem 0.65rem 1.1rem;
    }

    #chat .mes[is_user="true"]:not(.smallSysMes) .mes_block {
        width: min(100%, 31rem);
    }

    #chat .mes[is_user="true"]:not(.smallSysMes) .mes_text {
        width: min(100%, 29rem);
        padding: 0.72em 1.05em;
        border-width: 1px;
        line-height: 1.65;
    }

    #chat .mes[is_user="false"][is_system="false"] {
        --wc-character-message-pad-top: 0.95rem;
        --wc-character-message-pad-x: 0.35rem;
        --wc-character-page-padding: 0rem;
        --wc-character-page-border: 0rem;
        padding: 0.95rem 0.35rem 1.25rem;
    }

    #chat .mes[is_system="false"] {
        flex-direction: column;
    }

    #chat .mes[is_system="false"] > .mes_block {
        width: 100%;
        min-width: 0;
    }

    #chat .mes[is_system="false"] > .mes_block > .mes_text {
        box-sizing: border-box;
        margin-inline: auto;
        padding-inline: clamp(0.85rem, 4vw, 1.15rem);
    }

    #chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper {
        top: var(--wc-character-message-pad-top);
        left: 50%;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_block {
        width: 100%;
        padding: 0;
        border-width: 0;
        border-radius: 0;
        outline: none;
        box-shadow: none;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name {
        z-index: auto;
        display: flex;
        flex-direction: column;
        width: 100%;
        min-height: 0;
        aspect-ratio: auto;
        margin: 0 0 0.9rem;
        padding: 0;
        color: var(--wc-paper-light);
        border-radius: 0.45rem;
        letter-spacing: 0.045em;
        clip-path: none;
    }

    /* Grow the fallback behind, not over, the real portrait and carved shell. */
    #chat .mes[is_user="false"][is_system="false"] .ch_name::before {
        content: "";
        position: absolute;
        inset: 0;
        z-index: 0;
        background-color: var(--wc-walnut-soft);
        background-image: linear-gradient(rgba(24, 12, 6, 0.08), rgba(24, 12, 6, 0.24));
        border-radius: inherit;
        pointer-events: none;
    }

    /* Both metadata ancestors participate in flow; long text grows the header. */
    #chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container.flex1 {
        position: relative;
        inset: auto;
        z-index: auto;
        flex: none;
        width: 100%;
        height: auto;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container.flex1 > .flex-container.alignItemsBaseline {
        position: relative;
        inset: auto;
        z-index: auto;
        display: grid !important;
        grid-template-columns: 31% minmax(0, 1fr) 1.25em 21%;
        grid-template-rows: auto auto;
        height: auto;
        /* Minimum room for the unchanged round carving, never a height cap. */
        min-height: clamp(4.5rem, 26.4vw, 11.6rem);
        align-content: center;
        align-items: stretch !important;
        gap: 0.12rem 0;
        box-sizing: border-box;
        padding-block: 0.42rem;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name .name_text {
        grid-column: 2;
        grid-row: 1;
        align-self: end;
        justify-content: flex-start;
        width: 100%;
        padding: 0;
        color: var(--wc-paper-light);
        overflow: visible;
        overflow-wrap: anywhere;
        font-size: clamp(0.96rem, 4vw, 1.15rem);
        line-height: 1.08;
        letter-spacing: 0.06em;
        text-align: left;
        text-shadow: 0 -1px 0 rgba(18, 8, 3, 0.82);
        text-overflow: clip;
        white-space: normal;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name .mes_ghost {
        position: relative;
        z-index: 2;
        grid-column: 3;
        grid-row: 1;
        align-self: end;
        justify-self: end;
        margin: 0;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name .timestamp {
        grid-column: 2 / 4;
        grid-row: 2;
        align-self: start;
        display: block;
        width: 100%;
        color: var(--wc-gold-light);
        overflow: visible;
        overflow-wrap: anywhere;
        font-size: clamp(0.68rem, 2.7vw, 0.78rem);
        line-height: 1.3;
        text-align: left;
        text-shadow: 0 -1px 0 rgba(18, 8, 3, 0.82);
        text-overflow: clip;
        white-space: normal;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name .timestamp::before {
        color: var(--wc-gold-light);
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name > :is(.mes_buttons, .mes_edit_buttons) {
        z-index: 5;
        flex: none;
        align-self: stretch;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.25rem;
        min-width: 0;
        padding: 0.2rem 0.4rem;
        float: none;
        overflow: visible;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name .extraMesButtons {
        flex-wrap: wrap;
        min-width: 0;
        overflow: visible;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons > div) {
        box-sizing: border-box;
        min-width: 2.25rem;
        min-height: 2.25rem;
        padding: 0.6rem;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons > div):not(:disabled):not(.disabled):not([aria-disabled="true"]) {
        color: var(--wc-gold-light);
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_text {
        padding-inline: clamp(0.82rem, 4vw, 1.15rem);
        font-size: 1.05em;
        line-height: 1.72;
    }

    #chat .mes[is_user="false"][is_system="false"]:not(.smallSysMes) .mesAvatarWrapper .mesIDDisplay {
        color: var(--wc-gold-light);
        overflow: visible;
        font-size: clamp(0.52rem, 2.05vw, 0.62rem);
        white-space: normal;
        text-shadow: 0 -1px 0 rgba(18, 8, 3, 0.82);
    }

    #top-settings-holder {
        background-size: auto, 28rem auto;
    }

    #top-settings-holder::before,
    #top-settings-holder::after {
        font-size: 0.9rem;
    }

    #top-settings-holder::before {
        right: auto;
        left: 0.18rem;
    }

    #top-settings-holder::after {
        right: 0.18rem;
        left: auto;
    }

    #top-settings-holder .drawer-toggle {
        text-shadow:
            0 1px 0 rgba(255, 231, 161, 0.22),
            0 -1px 0 rgba(19, 9, 4, 0.78);
    }

    #send_form {
        border-width: 1px;
        background-size: auto, 28rem auto;
    }

    #form_sheld {
        padding: var(--wc-workbench-depth) 0.35rem calc(var(--wc-workbench-depth) + 0.08rem);
        border-width: 0.2rem;
        border-radius: 0;
    }

    #qr--bar {
        justify-content: flex-start;
        padding-inline: 0.2rem;
        overflow-x: auto;
    }

    #send_form #nonQRFormItems {
        column-gap: 0.28rem;
    }

    #send_form #send_textarea {
        min-width: 4rem;
        padding-inline: 0.65rem;
        border-width: 0.12rem;
    }

    #completion_prompt_manager #completion_prompt_manager_list li {
        grid-template-columns: minmax(0, 1fr) 3.3rem 2.5rem;
    }

    #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
        padding: 0.45em;
    }

    #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name {
        min-width: 0;
    }

    #completion_prompt_manager_popup {
        max-width: 100%;
        border-radius: 0;
    }

    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting {
        background-size: 30rem auto;
    }

    #select2-WIMultiSelector-results .select2-results__option {
        min-height: 2.3rem;
        padding-block: 0.45rem;
    }
}

@media screen and (max-width: 400px) {
    #chat .mes[is_user="false"][is_system="false"] .mes_text {
        font-size: 1.02em;
    }

    #send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop) {
        transform: none;
    }

    #send_form #send_textarea {
        flex: 1 1 auto;
        min-width: 0;
        max-width: 100%;
        padding-inline: 0.48rem;
        font-size: 0.86rem;
        line-height: 1.3;
        letter-spacing: 0;
    }

    #send_form #send_textarea::placeholder {
        font-size: 0.74rem;
        line-height: 1.3;
        letter-spacing: 0;
        text-align: left;
        white-space: nowrap;
    }

    #qr--bar > .qr--buttons .qr--button {
        padding: 0.2rem 0.38rem;
        margin-block: 0.14rem;
    }
}


/* ===== src/fallback.css ===== */
/*
 * 远程图片失败时的纯色与原生功能回退。
 * background-color、边框、文字和原生图标均先于图片声明存在。
 */

#chat,
#left-nav-panel,
#rm_api_block,
#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#Backgrounds,
#rm_extensions_block,
#PersonaManagement,
#right-nav-panel,
#completion_prompt_manager,
#completion_prompt_manager_popup,
.popup,
#dialogue_popup {
    background-color: var(--wc-paper);
}

#top-settings-holder,
#form_sheld,
#send_form,
#chat .mes[is_user="true"]:not(.smallSysMes) .mes_text {
    background-color: var(--wc-walnut);
}

#chat .mes[is_user="true"]:not(.smallSysMes) .mesAvatarWrapper {
    border-radius: 50%;
    box-shadow: inset 0 0 0 0.4rem var(--wc-walnut-soft), 0 0 0 0.5rem var(--wc-gold);
}

#chat .mes[is_user="true"]:not(.smallSysMes) .mesAvatarWrapper::after {
    background-color: transparent;
}
